describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      intercomAccessToken: 'test-intercom-token',
      zendeskApiToken: 'test-zendesk-token',
      zendeskSubdomain: 'testsubdomain',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as IntercomWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.conversationId).toBe('12345')
    expect(result.ticketId).toBe(12345)
    expect(result.ticketUrl).toBe('https://testsubdomain.zendesk.com/api/v2/tickets/12345.json')
  })
})

describe('handle', () => {
  it('throws when topic is missing', async () => {
    const payload = { data: { item: { id: '1', conversation_tags: [{ name: 'refund' }] } } } as unknown as IntercomWebhookPayload
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      zendeskApiToken: 'token',
      zendeskSubdomain: 'sub',
      fetch: vi.fn(),
    }
    await expect(handle(payload, config)).rejects.toThrow('Missing required field: topic')
  })

  it('throws when topic is not conversation.tag.created', async () => {
    const payload = { topic: 'other.topic', data: { item: { id: '1', conversation_tags: [{ name: 'refund' }] } } } as unknown as IntercomWebhookPayload
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      zendeskApiToken: 'token',
      zendeskSubdomain: 'sub',
      fetch: vi.fn(),
    }
    await expect(handle(payload, config)).rejects.toThrow('Unsupported topic: other.topic')
