    const payload = { topic: 'conversation.tag.created', data: { item: { id: '1', conversation_tags: [{ name: 'other' }] } } } as unknown as IntercomWebhookPayload
    const config: ConnectorConfig = {
      intercomAccessToken: 'token',
      zendeskApiToken: 'token',
      zendeskSubdomain: 'sub',
      fetch: vi.fn(),
    }
    await expect(handle(payload, config)).rejects.toThrow('Conversation does not have the "refund" tag')
  })

  it('fetches conversation details and creates ticket on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.method === 'GET' && req.url === 'https://api.intercom.io/conversations/12345') {
        return jsonResponse({
          type: 'conversation',
          id: '12345',
          url: 'https://app.intercom.io/a/apps/123/conversations/12345',
          subject: 'Refund request for order #123',
        })
      }
      if (req.method === 'POST' && req.url === 'https://testsub.zendesk.com/api/v2/tickets.json') {
        expect(req.json).toEqual({
          ticket: {
            subject: 'Refund request for order #123',
            comment: { body: 'View the conversation: https://app.intercom.io/a/apps/123/conversations/12345' },
          },
        })
        return jsonResponse({
          ticket: { id: 999, subject: 'Refund request for order #123', url: 'https://testsub.zendesk.com/api/v2/tickets/999.json' },
        }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

