        subject: 'Intercom Conversation 456',
        comment: { body: 'View the conversation: https://app.intercom.io/conversations/456' },
      },
    })
  })

  it('throws on non-2xx Intercom response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'not found' }, 404))

    const payload: IntercomWebhookPayload = {
      topic: 'conversation.tag.created',
      data: {
        item: {
          type: 'conversation',
          id: '12345',
